import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase, toJob, type JobRow } from './db.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

const MAX_BODY = 1024 * 1024;
const KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;

interface FieldError { field: string; message: string }

class HttpError extends Error {
  constructor(public status: number, public code: string, message: string, public fields?: FieldError[]) {
    super(message);
  }
}

const getById = db.prepare('SELECT * FROM jobs WHERE id = ?');
const getByKey = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?');
const listAll = db.prepare('SELECT * FROM jobs ORDER BY seq DESC');
const insertJob = db.prepare(`INSERT INTO jobs
  (id, status, input, steps, fail_attempts, attempts, progress, created_at, updated_at, run_after, idempotency_key, payload)
  VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?, 0, ?, ?)`);
const getBeat = db.prepare('SELECT beat_at FROM heartbeat WHERE id = 1');

function send(res: ServerResponse, status: number, body: unknown): void {
  const text = JSON.stringify(body);
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', 'content-length': Buffer.byteLength(text), 'cache-control': 'no-store' });
  res.end(text);
}

function sendError(res: ServerResponse, err: HttpError): void {
  const error: Record<string, unknown> = { code: err.code, message: err.message };
  if (err.fields) error.fields = err.fields;
  send(res, err.status, { error });
}

function readBody(req: IncomingMessage): Promise<string | null> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooBig = false;
    req.on('data', (c: Buffer) => {
      size += c.length;
      if (size > MAX_BODY) tooBig = true;
      else chunks.push(c);
    });
    req.on('end', () => resolve(tooBig ? null : Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

function isInt(v: unknown): v is number {
  return typeof v === 'number' && Number.isInteger(v);
}

async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const fields: FieldError[] = [];
  const rawKey = req.headers['idempotency-key'];
  let key: string | null = null;
  if (rawKey !== undefined) {
    const k = Array.isArray(rawKey) ? rawKey.join(',') : rawKey;
    if (!KEY_RE.test(k)) fields.push({ field: 'Idempotency-Key', message: 'must match ^[A-Za-z0-9_-]{1,128}$' });
    else key = k;
  }

  const ct = (req.headers['content-type'] ?? '').split(';')[0]!.trim().toLowerCase();
  const raw = await readBody(req);
  let body: unknown;
  let bodyOk = false;
  if (!ct) fields.push({ field: 'body', message: 'Content-Type must be application/json' });
  else if (ct !== 'application/json' && !/^application\/[a-z0-9.+-]*\+json$/.test(ct)) {
    fields.push({ field: 'body', message: 'Content-Type must be application/json' });
  } else if (raw === null) {
    fields.push({ field: 'body', message: 'body is too large' });
  } else {
    try {
      body = JSON.parse(raw);
      if (body === null || typeof body !== 'object' || Array.isArray(body)) {
        fields.push({ field: 'body', message: 'body must be a JSON object' });
      } else bodyOk = true;
    } catch {
      fields.push({ field: 'body', message: 'body must be valid JSON' });
    }
  }

  let input = '';
  let steps = 5;
  let failAttempts = 0;
  if (bodyOk) {
    const obj = body as Record<string, unknown>;
    for (const k of Object.keys(obj)) {
      if (k !== 'input' && k !== 'steps' && k !== 'failAttempts') fields.push({ field: k, message: 'unknown field' });
    }
    if (!Object.hasOwn(obj, 'input')) fields.push({ field: 'input', message: 'input is required' });
    else if (typeof obj.input !== 'string') fields.push({ field: 'input', message: 'input must be a string' });
    else if (obj.input.length < 1 || obj.input.length > 1000) fields.push({ field: 'input', message: 'input must be 1-1000 characters' });
    else if (obj.input.trim().length === 0) fields.push({ field: 'input', message: 'input must not be only whitespace' });
    else input = obj.input;

    if (Object.hasOwn(obj, 'steps')) {
      if (!isInt(obj.steps) || obj.steps < 1 || obj.steps > 20) fields.push({ field: 'steps', message: 'steps must be an integer from 1 to 20' });
      else steps = obj.steps;
    }
    if (Object.hasOwn(obj, 'failAttempts')) {
      if (!isInt(obj.failAttempts) || obj.failAttempts < 0 || obj.failAttempts > 5) fields.push({ field: 'failAttempts', message: 'failAttempts must be an integer from 0 to 5' });
      else failAttempts = obj.failAttempts;
    }
  }

  if (fields.length > 0) throw new HttpError(400, 'invalid_request', 'The request is invalid.', fields);

  const payload = JSON.stringify({ input, steps, failAttempts });
  const findExisting = (): boolean => {
    if (key === null) return false;
    const existing = getByKey.get(key) as JobRow | undefined;
    if (!existing) return false;
    if (existing.payload !== payload) {
      throw new HttpError(409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
    }
    send(res, 200, toJob(existing));
    return true;
  };
  if (findExisting()) return;

  const id = randomUUID();
  const now = new Date().toISOString();
  try {
    insertJob.run(id, input, steps, failAttempts, now, now, key, payload);
  } catch (e) {
    // Unique constraint on the key: another process inserted it concurrently.
    if (key !== null && findExisting()) return;
    throw e;
  }
  send(res, 201, toJob(getById.get(id) as unknown as JobRow));
}

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  let pathname: string;
  try {
    pathname = new URL(req.url ?? '/', 'http://localhost').pathname;
  } catch {
    throw new HttpError(404, 'not_found', 'Not found.');
  }
  const method = req.method ?? 'GET';
  const allow = (methods: string[]): void => {
    if (!methods.includes(method)) {
      res.setHeader('allow', methods.join(', '));
      throw new HttpError(405, 'method_not_allowed', `Method ${method} is not allowed on ${pathname}.`);
    }
  };

  if (pathname === '/') {
    allow(['GET']);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'no-store' });
    res.end(uiHtml);
    return;
  }
  if (pathname === '/health') {
    allow(['GET']);
    const row = getBeat.get() as { beat_at: number } | undefined;
    const up = !!row && Date.now() - row.beat_at <= 3000;
    return send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
  }
  if (pathname === '/api/jobs') {
    allow(['GET', 'POST']);
    if (method === 'GET') {
      const rows = listAll.all() as unknown as JobRow[];
      return send(res, 200, { jobs: rows.map(toJob) });
    }
    return createJob(req, res);
  }
  const m = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (m) {
    allow(['GET']);
    let id: string;
    try {
      id = decodeURIComponent(m[1]!);
    } catch {
      throw new HttpError(404, 'not_found', 'Job not found.');
    }
    const row = getById.get(id) as JobRow | undefined;
    if (!row) throw new HttpError(404, 'not_found', 'Job not found.');
    return send(res, 200, toJob(row));
  }
  throw new HttpError(404, 'not_found', 'Not found.');
}

const port = Number(process.env.PORT || 3000);
const server = createServer((req, res) => {
  handle(req, res).catch((err: unknown) => {
    if (res.headersSent) {
      res.destroy();
      return;
    }
    if (err instanceof HttpError) sendError(res, err);
    else {
      console.error(err);
      sendError(res, new HttpError(500, 'internal_error', 'Internal server error.'));
    }
  });
});
server.listen(port, () => console.log(`server listening on ${port}`));

let closing = false;
function shutdown(): void {
  if (closing) return;
  closing = true;
  server.close(() => {
    try { db.close(); } catch { /* ignore */ }
    process.exit(0);
  });
  server.closeAllConnections?.();
  setTimeout(() => process.exit(0), 3000).unref();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

