function heartbeat(): void {
  try {
    beat.run(Date.now());
  } catch (e) {
    console.error('heartbeat failed', e);
  }
}
heartbeat();
const beatTimer = setInterval(heartbeat, 500);

const findCandidate = db.prepare(`SELECT * FROM jobs
  WHERE (status = 'queued' AND run_after <= ?) OR (status = 'running' AND lease_until < ?)
  ORDER BY seq ASC LIMIT 1`);
const startAttempt = db.prepare(`UPDATE jobs SET status = 'running', attempts = ?, progress = 0,
  output = NULL, error = NULL, lease_until = ?, updated_at = ? WHERE id = ?`);
const stepDone = db.prepare(`UPDATE jobs SET progress = ?, lease_until = ?, updated_at = ?
  WHERE id = ? AND status = 'running' AND attempts = ?`);
const complete = db.prepare(`UPDATE jobs SET status = 'completed', progress = ?, output = ?, error = NULL,
  lease_until = 0, updated_at = ? WHERE id = ? AND status = 'running' AND attempts = ?`);
const retry = db.prepare(`UPDATE jobs SET status = 'queued', progress = 0, run_after = ?, lease_until = 0,
  updated_at = ? WHERE id = ? AND status = 'running' AND attempts = ?`);
const fail = db.prepare(`UPDATE jobs SET status = 'failed', progress = 0, output = NULL, error = ?,
  lease_until = 0, updated_at = ? WHERE id = ? AND status = 'running' AND attempts = ?`);

/** Atomically claims the oldest runnable job and starts a new attempt on it. */
function claim(): { id: string; input: string; steps: number; failAttempts: number; attempt: number } | null {
  db.exec('BEGIN IMMEDIATE');
  try {
    const now = Date.now();
    const row = findCandidate.get(now, now) as JobRow | undefined;
    if (!row) {
      db.exec('COMMIT');
      return null;
    }
    const attempt = Math.min(row.attempts + 1, MAX_ATTEMPTS);
    startAttempt.run(attempt, now + LEASE_MS, new Date(now).toISOString(), row.id);
    db.exec('COMMIT');
    return { id: row.id, input: row.input, steps: row.steps, failAttempts: row.fail_attempts, attempt };
  } catch (e) {
    try { db.exec('ROLLBACK'); } catch { /* ignore */ }
    throw e;
  }
