  const { id, attempt } = job;
  for (let i = 1; i <= job.steps; i++) {
    await sleep(STEP_MS);
    if (stopping) {
      // Hand the job back so it is picked up again on restart.
      retry.run(0, new Date().toISOString(), id, attempt);
      return;
    }
    if (i === 1 && attempt <= job.failAttempts) {
      const now = Date.now();
      if (attempt >= MAX_ATTEMPTS) {
        fail.run('transient failure', new Date(now).toISOString(), id, attempt);
        console.log(`job ${id} failed after ${attempt} attempts`);
      } else {
        retry.run(now + RETRY_DELAY_MS, new Date(now).toISOString(), id, attempt);
        console.log(`job ${id} attempt ${attempt} failed; retrying`);
      }
      return;
    }
    const now = Date.now();
    if (i < job.steps) {
      const r = stepDone.run(i, now + LEASE_MS, new Date(now).toISOString(), id, attempt);
      if (r.changes === 0) return; // lost ownership
    } else {
      complete.run(i, job.input.toUpperCase(), new Date(now).toISOString(), id, attempt);
      console.log(`job ${id} completed`);
    }
  }
}

