  try {
    job = claim();
  } catch (e) {
    console.error('claim failed', e);
  }
  if (job) {
    try {
      await processJob(job);
    } catch (e) {
      console.error('processing failed', e);
    }
    continue;
  }
  await new Promise<void>((resolve) => {
    wake = resolve;
    setTimeout(resolve, POLL_MS);
  });
  wake = null;
}

clearInterval(beatTimer);
try {
  db.exec('DELETE FROM heartbeat');
  db.close();
} catch { /* ignore */ }
process.exit(0);

